            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1) * (c1-c0+1)
                        matches = sum(grid[r][c] == color
                                      for r in range(r0, r1+1)
                                      for c in range(c0, c1+1))
                        if matches / area < 0.75:
                            continue
                        if any(sum(grid[r][c] == color for c in range(c0,c1+1)) < (c1-c0+1)*0.5
                               for r in range(r0,r1+1)):
                            continue
                        if any(sum(grid[r][c] == color for r in range(r0,r1+1)) < (r1-r0+1)*0.5
                               for c in range(c0,c1+1)):
                            continue
                        candidates.append((matches, area, color, r0, r1, c0, c1))
    candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
    chosen = []
    for cand in candidates:
        _, area, color, r0, r1, c0, c1 = cand
        duplicate = False
        for _, a2, col2, u0, u1, v0, v1 in chosen:
            if color != col2:
                continue
            overlap = max(0, min(r1,u1)-max(r0,u0)+1) * max(0, min(c1,v1)-max(c0,v0)+1)
            if overlap / min(area, a2) > 0.6:
                duplicate = True
                break
        if not duplicate:
            chosen.append(cand)
    out = [[bg for _ in range(w)] for _ in range(h)]
    for _, _, color, r0, r1, c0, c1 in chosen:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out

