        # per column, and overall.
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count / area < 0.80:
                            continue
                        if any(sum(grid[r][c] == color for c in range(c0, c1 + 1)) / width < 0.80
                               for r in range(r0, r1 + 1)):
                            continue
                        if any(sum(grid[r][c] == color for r in range(r0, r1 + 1)) / height < 0.80
                               for c in range(c0, c1 + 1)):
                            continue
                        boxes.append((color, r0, r1, c0, c1, count, area))
    # Consider largest candidate first; smaller heavily-overlapping candidates
    # are merely fragments of a noisy rectangle already selected.
    boxes.sort(key=lambda b: (b[6], b[5]), reverse=True)
    selected = []
